    "FilePath": "file:///node_modules/@pragmatic-tech-ai/todl/dist/codegen/tests/fixtures/demo-app.package.generated.d.ts",
    "Content": "import { ModelDataSource, ReflectedEntity, ModelRegistry } from \"../../../index.js\";\nimport type { EntityReader, IModelDataConnector, InstanceDescriptor, TodlDocument } from \"../../../index.js\";\nexport declare class DemoApp extends ModelDataSource {\n    constructor(connector?: IModelDataConnector);\n    static fromJSON(doc: TodlDocument): DemoApp;\n    protected createEntity(reader: EntityReader): ReflectedEntity;\n    get aServices(): readonly AService[];\n    get todlElements(): readonly TodlElement[];\n    aService(id: string, fields: {\n        description?: string;\n        label?: string;\n        name: string;\n    }): InstanceDescriptor;\n    todlElement(id: string, fields: {\n        description?: string;\n        label?: string;\n    }): InstanceDescriptor;\n}\nexport declare class AService extends ReflectedEntity {\n    get description(): string;\n    get label(): string;\n    get name(): string;\n}\nexport declare class TodlElement extends ReflectedEntity {\n    get description(): string;\n    get label(): string;\n}\nexport declare class AppRegistry {\n    static Create(): ModelRegistry;\n}\n"
