    "Content": "import { ModelDataSource, ReflectedEntity } from \"../../../index.js\";\nimport type { EntityReader, IModelDataConnector, InstanceDescriptor, TodlDocument } from \"../../../index.js\";\nexport declare class TechCatalog extends ModelDataSource {\n    constructor(connector?: IModelDataConnector);\n    static fromJSON(doc: TodlDocument): TechCatalog;\n    protected createEntity(reader: EntityReader): ReflectedEntity;\n    get billings(): readonly Billing[];\n    get locations(): readonly Location[];\n    get technologies(): readonly Technology[];\n    get stack(): readonly Technology[];\n    billing(id: string, fields: {\n        label: string;\n    }): InstanceDescriptor;\n    location(id: string, fields: {\n        label: string;\n    }): InstanceDescriptor;\n    technology(id: string, fields: {\n        label: string;\n        availableIn?: readonly Location[];\n        billing?: Billing;\n    }): InstanceDescriptor;\n}\nexport declare class Billing extends ReflectedEntity {\n    get label(): string;\n}\nexport declare class Location extends ReflectedEntity {\n    get label(): string;\n}\nexport declare class Technology extends ReflectedEntity {\n    get label(): string;\n    get tags(): string;\n    get availableIn(): readonly Location[];\n    get billing(): Billing | undefined;\n}\n"
